import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse(`{"title":"Page 16 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"16","title":"Page 16 | Home","prev":"/page/15/","next":"/page/17/","posts":[{"title":"Vue下使用jest进行单元测试","url":"/posts/2020-03-19-vue-jest/","date":"2020-03-19 21:56","tags":["frontend","vue"],"html":"<p>在前端开发逐渐复杂的今天，当然也需要对前端进行测试。单元测试主要用于白盒测试，检测程序的最小单位的正确性，通常来说就是验证函数的输入和输出。</p>\\n<h2 id=\\"vue-集成-jest\\" tabindex=\\"-1\\">vue 集成 jest <a class=\\"header-anchor\\" href=\\"#vue-集成-jest\\" aria-label=\\"Permalink to &quot;vue 集成 jest&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>vue-cli 已经提供现成的<a href=\\"https://cli.vuejs.org/core-plugins/unit-jest.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">插件</a>，我们可以很方便的进行集成。官方文档也有讲述如何 debug。在使用 jest 之前，我们需要知道 jest 的测试代码不是像前端代码一样运行在浏览器环境，而是使用 node 运行，并且浏览器的 DOM 环境使用<a href=\\"https://github.com/jsdom/jsdom\\" target=\\"_blank\\" rel=\\"noreferrer\\">jsdom</a>来模拟，所以在集成测试的时候需要解决不少问题。</p>\\n<h2 id=\\"jest-与-webpack\\" tabindex=\\"-1\\">jest 与 webpack <a class=\\"header-anchor\\" href=\\"#jest-与-webpack\\" aria-label=\\"Permalink to &quot;jest 与 webpack&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当今的前端开发都离不开 webpack 进行打包，我们使用各种各样的 loader 来处理代码，所以可以使用例如<code>import</code>语法来引用 JS 文件，但是 node 环境目前还不支持原生的 es6 <code>import</code>文件。所以在使用 jest 的时候，我们需要用 babel 进行代码转换，好在 @vue/cli-plugin-unit-jest 都已经给配置好了，使用预置的 preset 就行。我是基于 TS 开发，所以用的 preset 是 <code>@vue/cli-plugin-unit-jest/presets/typescript-and-babel</code>。但是我们在代码里使用的一些 webpack 的特殊语法就不太好对应了，例如我有使用<a href=\\"https://webpack.js.org/concepts/loaders/#inline\\" target=\\"_blank\\" rel=\\"noreferrer\\">inline loader</a>来打包特殊的 SVG 文件到代码中，但是在测试的时候就会遇到无法 import 的尴尬问题。这时候的解决方案就是使用<code>moduleNameMapper</code>:</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">moduleNameMapper</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">    '^!svg-inline-loader!@(.*)$'</span><span style=\\"color:#24292E\\">: require.</span><span style=\\"color:#6F42C1\\">resolve</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'jest-transform-stub'</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>通过把 import 的资源文件映射为空，就能解决 jest 运行出错的问题，毕竟我们在做单元测试的时候不会检测资源文件。</p>\\n<h2 id=\\"jest-mock-vuex-store\\" tabindex=\\"-1\\">jest mock vuex store <a class=\\"header-anchor\\" href=\\"#jest-mock-vuex-store\\" aria-label=\\"Permalink to &quot;jest mock vuex store&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>做单元测试的时候，mock 是非常常见的需求，例如我们在一个文件里引用了 store 的数据，但是要构造这个数据非常复杂，所以我们需要直接 mock 数据。这里需要注意的是，如果是 import 引入的话，我们需要先 mock 再使用动态引用的方式加载测试模块，保证是在 import 之前 mock 数据。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">jest.</span><span style=\\"color:#6F42C1\\">doMock</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'@/store'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  state: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    account: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      hello: </span><span style=\\"color:#032F62\\">'world'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#24292E\\"> { </span><span style=\\"color:#E36209\\">default</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">formatter</span><span style=\\"color:#24292E\\"> } </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> await</span><span style=\\"color:#D73A49\\"> import</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'@/utils/formatter'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>不过，mock 之后记得 reset：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">beforeEach</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  jest.</span><span style=\\"color:#6F42C1\\">resetModules</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"jest-mock-navigator\\" tabindex=\\"-1\\">jest mock navigator <a class=\\"header-anchor\\" href=\\"#jest-mock-navigator\\" aria-label=\\"Permalink to &quot;jest mock navigator&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有些测试用例中，我们需要 mock 用户的浏览器是不同语言，这个时候就需要使用<code>spyOn</code>来修改属性的返回值。示例代码如下：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">describe</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'test i18n'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  let</span><span style=\\"color:#24292E\\"> languageGetter</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> jest</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">SpyInstance</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  beforeEach</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    jest.</span><span style=\\"color:#6F42C1\\">resetModules</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    languageGetter </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> jest.</span><span style=\\"color:#6F42C1\\">spyOn</span><span style=\\"color:#24292E\\">(window.navigator, </span><span style=\\"color:#032F62\\">'language'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'get'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  it</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'set lang is zh-CN'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    languageGetter.</span><span style=\\"color:#6F42C1\\">mockReturnValue</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'zh-CN'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(navigator.language); </span><span style=\\"color:#6A737D\\">// zh-CN</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><h2 id=\\"jest-mock-vue-router\\" tabindex=\\"-1\\">jest mock vue router <a class=\\"header-anchor\\" href=\\"#jest-mock-vue-router\\" aria-label=\\"Permalink to &quot;jest mock vue router&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>测试 Vue 组件主要依靠<a href=\\"https://vue-test-utils.vuejs.org/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Vue Test Utils</a>。官方文档也有介绍如何使用，这个仅给出一个例子来描述用法：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> { mount, createLocalVue } </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> '@vue/test-utils'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> VueRouter </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> 'vue-router'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> App </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> '@/App.vue'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> routes </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> '@/router/routes'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> HelloWorld </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> '@/views/HelloWorld.vue'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> localVue</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> createLocalVue</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">localVue.</span><span style=\\"color:#6F42C1\\">use</span><span style=\\"color:#24292E\\">(VueRouter);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">describe</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'Test index routes'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  it</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'should find HelloWorld when router is HelloWorld'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">async</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> router</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> VueRouter</span><span style=\\"color:#24292E\\">({ routes, mode: </span><span style=\\"color:#032F62\\">'history'</span><span style=\\"color:#24292E\\"> });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    await</span><span style=\\"color:#24292E\\"> router.</span><span style=\\"color:#6F42C1\\">push</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'/helloworld'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> wrapper</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> mount</span><span style=\\"color:#24292E\\">(App, {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      localVue,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      router</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    expect</span><span style=\\"color:#24292E\\">(wrapper.</span><span style=\\"color:#6F42C1\\">find</span><span style=\\"color:#24292E\\">(HelloWorld).</span><span style=\\"color:#6F42C1\\">exists</span><span style=\\"color:#24292E\\">()).</span><span style=\\"color:#6F42C1\\">toBe</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br></div></div><p>这里使用 localVue 的原因是项目中只有一个 Vue 实例，直接使用的话会污染原本的 Vue，所以要在测试代码里手动创建<code>router</code>。这里要注意的是，如果 find 是某个组件，需要在 Vue 组件里面显示声明<code>name</code>，否则在 Lazy Loading 的情况下是无法找到组件的。还有一个指得注意的是<code>router.push</code> 是一个 Promise 异步操作，所以如果写成同步的话，会一直找不到组件的。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>jest 集成了很多测试的工具，只装一个工具便可进行单元测试。但是由于不是运行在浏览器环境，导致<code>jsdom</code>不支持的特性都需要自己来处理。所以希望选择一个在浏览器运行单元测试的框架应该会少遇到很多坑吧。特别是用了很多浏览器特性的前端项目，测试起来更加折腾。</p>\\n<h2 id=\\"引用\\" tabindex=\\"-1\\">引用 <a class=\\"header-anchor\\" href=\\"#引用\\" aria-label=\\"Permalink to &quot;引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://jestjs.io/docs/en/webpack\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using with webpack</a></p>\\n<p><a href=\\"https://lmiller1990.github.io/vue-testing-handbook/vue-router.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Test Vue Router</a></p>\\n"},{"title":"前端开发如何防止逆向以及对策","url":"/posts/2020-02-22-hack-dev-tools/","date":"2020-02-22 18:03","tags":["frontend"],"html":"<p>前端开发分析代码的途径最简单不过了，第一个途径是查看网页源代码，第二个途径是打开开发者工具审查元素。</p>\\n<h2 id=\\"防止查看源代码\\" tabindex=\\"-1\\">防止查看源代码 <a class=\\"header-anchor\\" href=\\"#防止查看源代码\\" aria-label=\\"Permalink to &quot;防止查看源代码&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现在网站的基本对策是禁用用户右键选项菜单来避免查看源代码。首先，源代码肯定是能查看到的。采取的措施也只不过是掩耳盗铃而已。解决对策也有很多，我随便说几个。</p>\\n<p>第一，针对 Chrome 浏览器，我们可以直接在地址栏里输入 <code>view-source:https://www.google.com/</code> 这种方式来查看源代码。第二，我们可以使用其他工具，例如<code>curl</code>, <code>wget</code>来直接下载源代码。这种是很初级的防范对策。</p>\\n<h2 id=\\"防止审查元素\\" tabindex=\\"-1\\">防止审查元素 <a class=\\"header-anchor\\" href=\\"#防止审查元素\\" aria-label=\\"Permalink to &quot;防止审查元素&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现代化的前端开发，都是基于 JS 来渲染页面元素的，有时候我们查看源代码也只是看到了 JS 文件的引用。没有太大意义，所以需要浏览器渲染之后查看真正的 DOM 元素才有意义。这时候如何禁止审查元素就是另外一种对策了。\\n现在用来检测打开开发者工具主要是通过判断<code>console.log</code>的执行，因为不打开开发者工具的话<code>console.log</code>是不会执行的。所以有些网站就可以利用这个来阻止用户打开开发者工具审查元素和 Debug 代码。\\n下面给出一个例子来：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">script</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">let el = new Image();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">Object.defineProperty(el,'id',{get: </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\">(){window.location.href</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"http://www.bimibimi.tv\\"</span><span style=\\"color:#24292E\\">}});</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">console.log(el);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">script</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>这是一个非常巧妙的例子，当执行<code>console.log</code>输出 Image 元素的时候，比如会访问 id 属性，从而触发后面的重定向 URL 代码。所以表现就是用户试图打开开发者面板就会被自动定位到首页。</p>\\n<p>要破解这个的话，只能在页面执行之前注入代码修改 Image 函数的使用：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">Image</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> () {};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">Object.</span><span style=\\"color:#6F42C1\\">defineProperty</span><span style=\\"color:#24292E\\">(window, </span><span style=\\"color:#032F62\\">'Image'</span><span style=\\"color:#24292E\\">, { writable: </span><span style=\\"color:#005CC5\\">false</span><span style=\\"color:#24292E\\"> });</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>通过注入上面的代码，来规避自动跳转到首页。如何注入呢？ 就需要利用 Chrome 的扩展功能，详细代码请参照<a href=\\"https://github.com/acgotaku/bimibimi-hack\\" target=\\"_blank\\" rel=\\"noreferrer\\">bimibimi-hack</a>。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端代码逆向和反逆向，永远没有银弹。只能说是提高逆向的门槛，但想完全防止是不可能的。如果自己编译一个浏览器，修改浏览器的默认行为的话，就没有不能调试的网站。</p>\\n<h2 id=\\"引用\\" tabindex=\\"-1\\">引用 <a class=\\"header-anchor\\" href=\\"#引用\\" aria-label=\\"Permalink to &quot;引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://stackoverflow.com/questions/7798748/find-out-whether-chrome-console-is-open\\" target=\\"_blank\\" rel=\\"noreferrer\\">Find out whether Chrome console is open</a></p>\\n<p><a href=\\"view-source:http://www.bimibimi.tv/bangumi/640/play/1/1/\\">Source code of bimibimi.tv</a></p>\\n"},{"title":"前端部署之CDN的那些事情","url":"/posts/2020-01-14-frontend-deploy/","date":"2020-01-14 22:59","tags":["frontend"],"html":"<p>现在的前端开发主流是 PWA，简而言之就是像 App 一样使用。基于 PWA 技术可以离线访问，并且可以添加程序到菜单里。离线技术使用的是比较成熟的 Service Workers。但是配合 CDN 就有很多不得不注意的事情。</p>\\n<h2 id=\\"cdn-部署静态资源\\" tabindex=\\"-1\\">CDN 部署静态资源 <a class=\\"header-anchor\\" href=\\"#cdn-部署静态资源\\" aria-label=\\"Permalink to &quot;CDN 部署静态资源&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现代化前端开发主要是把 CSS，JS，图片等静态资源放在 CDN 上有效提高载入速度。把静态 HTML 文件放在服务器上，有利于更新网站最新状态，例如进入维护状态，直接把静态 HTML 文件替换为维护页面即可。</p>\\n<h2 id=\\"同源策略问题\\" tabindex=\\"-1\\">同源策略问题 <a class=\\"header-anchor\\" href=\\"#同源策略问题\\" aria-label=\\"Permalink to &quot;同源策略问题&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>正常情况下，资源文件和主网站不在同一个域名下，例如主网站是<code>icehoney.me</code>，资源网站是<code>static.icehoney.me</code>。当然了，资源文件使用 GET 方法浏览器自动载入，没有任何问题。但是注册 Service Worker 的 JS 文件是不能放在 CDN 上的，因为这是官方的规定。个人理解是出于安全因素的考虑。所以我们在主服务器上不仅要放静态的 HTML 文件，还要放一个 serive-worker.js 文件。</p>\\n<h2 id=\\"svg-symbol-的使用问题\\" tabindex=\\"-1\\">SVG symbol 的使用问题 <a class=\\"header-anchor\\" href=\\"#svg-symbol-的使用问题\\" aria-label=\\"Permalink to &quot;SVG symbol 的使用问题&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现在前端的开发针对很多小图标，都是采用 SVG 的方式来引用。其中 SVG symbol 特别好用，可以在页面里嵌入一个 inline 的 SVG，然后在其他对方使用<code>&lt;use&gt;</code>标签来引用。但是对于放在 CDN 上的 SVG 文件，不能直接使用下面的形式：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">use</span><span style=\\"color:#6F42C1\\"> xlink</span><span style=\\"color:#24292E\\">:</span><span style=\\"color:#6F42C1\\">href</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"https://static.icehoney.me/icon.svg#china\\"</span><span style=\\"color:#24292E\\"> /></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>如果引用 CDN 的 SVG 浏览器会报错，解决方案是使用<code>svg-inline-loader</code>，手动在 HTML 里面注入 SVG 文件。<code>document.body.insertAdjacentHTML</code> 方法可以注入 inline 的 SVG。</p>\\n<h2 id=\\"workbox-配置\\" tabindex=\\"-1\\">Workbox 配置 <a class=\\"header-anchor\\" href=\\"#workbox-配置\\" aria-label=\\"Permalink to &quot;Workbox 配置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先，PWA 项目的路由都是由前端来处理，所以我们需要使用<code>navigateFallback</code>保证不管导航到哪个路由都能映射到缓存的 HTML 文件。然后是使用<code>runtimeCaching</code>配置缓存服务器请求。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>由于 Service Workers 的导入使得 CDN 部署变得有些麻烦，不过这些问题好在都能找到解决方案。还有一点是 Chrome 的 Network 面板里的 offline 模式不能测试 Service Workers 的离线。需要自己手动拔网线才能测试。</p>\\n<h2 id=\\"引用\\" tabindex=\\"-1\\">引用 <a class=\\"header-anchor\\" href=\\"#引用\\" aria-label=\\"Permalink to &quot;引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/w3c/ServiceWorker/issues/940\\" target=\\"_blank\\" rel=\\"noreferrer\\">Is it possible to serve service workers from CDN/remote origin?</a></p>\\n<p><a href=\\"https://developers.google.com/web/tools/workbox/modules/workbox-webpack-plugin\\" target=\\"_blank\\" rel=\\"noreferrer\\">Workbox webpack Plugins</a></p>\\n"}]},"relativePath":"page/16/index.md","filePath":"page/[page].md"}`),e={name:"page/16/index.md"};function l(p,o,r,t,c,i){return a(),n("div")}const b=s(e,[["render",l]]);export{u as __pageData,b as default};
